{"summary": "Search Answer sheet for formulas and non-empty cells", "command": "python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx',data_only=False)
ws=wb['Answer']
formulas=[]
nonempty=[]
for row in ws.iter_rows():
    for cell in row:
        if cell.value is None or cell.value=='':
            continue
        if isinstance(cell.value,str) and cell.value.startswith('='):
            formulas.append((cell.coordinate,cell.value))
        else:
            nonempty.append((cell.coordinate,cell.value))
print('Non-empty count',len(nonempty),'Formula count',len(formulas))
print('First nonempty:',nonempty[:20])
print('First formulas:',formulas[:20])
