import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx',data_only=False)
for name in ['Value','Volume','Total Reserves']:
    ws=wb[name]
    # find 2023 in col A
    year_row=None
    for r in range(1,ws.max_row+1):
        if ws.cell(r,1).value==2023:
            year_row=r
            break
    print(name,'year_row',year_row,'max_row',ws.max_row,'max_col',ws.max_column)
    # print rows 1-12 col1-8
    print('Top rows:')
    for r in range(1,13):
        vals=[ws.cell(r,c).value for c in range(1,9)]
        if any(v is not None for v in vals):
            print(r,vals)
    print('Bottom rows:')
    for r in range(ws.max_row-5,ws.max_row+1):
        vals=[ws.cell(r,c).value for c in range(1,9)]
        if any(v is not None for v in vals):
            print(r,vals)
    print('-----')
