import openpyxl
from openpyxl.utils import get_column_letter
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx',data_only=False)
ws=wb['Answer']

def fill_sig(cell):
    f=cell.fill
    if f is None:
        return None
    if f.patternType is None and f.fgColor is None and f.bgColor is None:
        return None
    # openpyxl default is patternType None and colors are '00000000'? let's show raw
    return (f.patternType, f.fgColor.type if f.fgColor else None, f.fgColor.rgb if f.fgColor else None, f.fgColor.indexed if f.fgColor else None)

for r in range(1,15):
    for c in range(1,12):
        cell=ws.cell(r,c)
        if cell.value is None:
            sig=fill_sig(cell)
            if sig and sig[2] not in (None,'00000000','000000'):
                print('blank filled', r, get_column_letter(c), sig)

# Also check any cell in rows 3-6 with non-default fill regardless of value
print('Rows 3-6 fills:')
for r in range(3,7):
    for c in range(1,12):
        cell=ws.cell(r,c)
        sig=fill_sig(cell)
        if sig and sig[2] not in (None,'00000000','000000'):
            print(r,get_column_letter(c),cell.value,sig)
